PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE migration ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" VARCHAR, "group_id" INTEGER, "migrated_at" TIMESTAMP NOT NULL DEFAULT current_timestamp);
CREATE TABLE migration_lock ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "table_name" VARCHAR, UNIQUE ("table_name"));
CREATE TABLE IF NOT EXISTS "organizations" ("id" text NOT NULL, "display_name" text NOT NULL, updated_at TIMESTAMP, created_at TIMESTAMP, name TEXT, alias TEXT, key BIGINT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "saved_views" ("id" text NOT NULL, "name" text NOT NULL, "category" text NOT NULL, "created_by" text, "updated_by" text, "source_page" text NOT NULL, "tags" text, "data" text NOT NULL, "extra_data" text, created_at TIMESTAMP, updated_at TIMESTAMP, org_id TEXT REFERENCES organizations(id) ON DELETE CASCADE, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "pipelines" ("id" text NOT NULL, "order_id" INTEGER, "enabled" BOOLEAN, "created_by" text, "created_at" TIMESTAMP DEFAULT current_timestamp, "name" varchar(400) NOT NULL, "alias" varchar(20) NOT NULL, "description" text, "filter" text NOT NULL, "config_json" text, org_id TEXT REFERENCES organizations(id) ON DELETE CASCADE, updated_by TEXT, updated_at TIMESTAMP, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "notification_channel" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "name" VARCHAR, "type" VARCHAR, "data" VARCHAR, "org_id" VARCHAR, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "alertmanager_config" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "config" text NOT NULL, "hash" text NOT NULL, "org_id" VARCHAR NOT NULL, PRIMARY KEY ("id"), UNIQUE ("org_id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "alertmanager_state" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "silences" text, "nflog" text, "org_id" VARCHAR NOT NULL, PRIMARY KEY ("id"), UNIQUE ("org_id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "apdex_setting" ("id" text NOT NULL, "org_id" text, "service_name" text, "threshold" float NOT NULL, "exclude_status_codes" text NOT NULL, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "ttl_setting" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "transaction_id" text NOT NULL, "table_name" text NOT NULL, "ttl" INTEGER NOT NULL DEFAULT 0, "cold_storage_ttl" INTEGER NOT NULL DEFAULT 0, "status" text NOT NULL, "org_id" VARCHAR NOT NULL, "condition" TEXT, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "virtual_field" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, "name" text NOT NULL, "expression" text NOT NULL, "description" text, "signal" text NOT NULL, "org_id" text NOT NULL, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "installed_integration" ("id" text NOT NULL, "type" text, "config" text, "installed_at" TIMESTAMP DEFAULT current_timestamp, "org_id" text, PRIMARY KEY ("id"), CONSTRAINT "org_id_type" UNIQUE ("type", "org_id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "cloud_integration" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "provider" text, "config" text, "account_id" text, "last_agent_report" text, "removed_at" timestamp, "org_id" text, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "rule" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, "deleted" INTEGER NOT NULL DEFAULT 0, "data" text NOT NULL, "org_id" text, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "planned_maintenance" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, "name" text NOT NULL, "description" text, "schedule" text NOT NULL, "org_id" text, "scope" TEXT, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "quick_filter" ("id" text NOT NULL, "org_id" text NOT NULL, "filter" text NOT NULL, "signal" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, PRIMARY KEY ("id"), CONSTRAINT "org_id_signal" UNIQUE ("org_id", "signal"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "factor_password" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "password" text NOT NULL, "temporary" boolean NOT NULL, "user_id" text NOT NULL, PRIMARY KEY ("id"), FOREIGN KEY ("user_id") REFERENCES "users" ("id"));
CREATE TABLE IF NOT EXISTS "reset_password_token" ("id" text NOT NULL, "token" text NOT NULL, "password_id" text NOT NULL, "expires_at" TIMESTAMP, PRIMARY KEY ("id"), FOREIGN KEY ("password_id") REFERENCES "factor_password" ("id"));
CREATE TABLE IF NOT EXISTS "license" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "key" text NOT NULL, "data" text, "last_validated_at" TIMESTAMP NOT NULL, "org_id" text NOT NULL, PRIMARY KEY ("id"), UNIQUE ("key"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "trace_funnel" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, "name" text NOT NULL, "description" text, "org_id" varchar NOT NULL, "steps" text NOT NULL, "tags" text, PRIMARY KEY ("id"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "agent" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "agent_id" text NOT NULL, "org_id" text NOT NULL, "terminated_at" TIMESTAMP, "status" text NOT NULL, "config" text NOT NULL, PRIMARY KEY ("id"), UNIQUE ("agent_id"));
CREATE TABLE IF NOT EXISTS "agent_config_version" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" text, "updated_by" text, "org_id" text NOT NULL, "version" INTEGER, "element_type" text NOT NULL, "deploy_status" text NOT NULL DEFAULT 'dirty', "deploy_sequence" INTEGER, "deploy_result" text, "hash" text, "config" text, PRIMARY KEY ("id"), CONSTRAINT "element_version_org_idx" UNIQUE ("org_id", "version", "element_type"), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "agent_config_element" ("id" text NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "element_id" text NOT NULL, "element_type" text NOT NULL, "version_id" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "element_type_version_idx" UNIQUE ("element_id", "element_type", "version_id"), FOREIGN KEY ("version_id") REFERENCES "agent_config_version" ("id"));
CREATE TABLE IF NOT EXISTS "route_policy" ("id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "created_by" TEXT NOT NULL, "updated_by" TEXT NOT NULL, "expression" TEXT NOT NULL, "kind" TEXT NOT NULL, "channels" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "tags" TEXT, "org_id" TEXT NOT NULL, CONSTRAINT "pk_route_policy" PRIMARY KEY ("id"), CONSTRAINT "fk_route_policy_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "auth_token" ("id" TEXT NOT NULL, "meta" TEXT NOT NULL, "prev_access_token" TEXT, "access_token" TEXT NOT NULL, "prev_refresh_token" TEXT, "refresh_token" TEXT NOT NULL, "last_observed_at" TIMESTAMP, "rotated_at" TIMESTAMP, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "user_id" TEXT NOT NULL, CONSTRAINT "pk_auth_token" PRIMARY KEY ("id"), CONSTRAINT "fk_auth_token_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id"));
CREATE TABLE IF NOT EXISTS "tuple" ("store" TEXT NOT NULL, "object_type" TEXT NOT NULL, "object_id" TEXT NOT NULL, "relation" TEXT NOT NULL, "user_object_type" TEXT NOT NULL, "user_object_id" TEXT NOT NULL, "user_relation" TEXT NOT NULL, "user_type" TEXT NOT NULL, "ulid" TEXT NOT NULL, "inserted_at" TIMESTAMP NOT NULL, "condition_name" TEXT, "condition_context" TEXT, CONSTRAINT "pk_tuple" PRIMARY KEY ("store", "object_type", "object_id", "relation", "user_object_type", "user_object_id", "user_relation"));
CREATE TABLE IF NOT EXISTS "authorization_model" ("store" TEXT NOT NULL, "authorization_model_id" TEXT NOT NULL, "schema_version" TEXT NOT NULL DEFAULT 1.1, "serialized_protobuf" TEXT NOT NULL, CONSTRAINT "pk_authorization_model" PRIMARY KEY ("store", "authorization_model_id"));
CREATE TABLE IF NOT EXISTS "store" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP, "deleted_at" TIMESTAMP, CONSTRAINT "pk_store" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "assertion" ("store" TEXT NOT NULL, "authorization_model_id" TEXT NOT NULL, "assertions" TEXT, CONSTRAINT "pk_assertion" PRIMARY KEY ("store", "authorization_model_id"));
CREATE TABLE IF NOT EXISTS "public_dashboard" ("id" TEXT NOT NULL, "time_range_enabled" BOOLEAN NOT NULL, "default_time_range" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "dashboard_id" TEXT NOT NULL, CONSTRAINT "pk_public_dashboard" PRIMARY KEY ("id"), CONSTRAINT "fk_public_dashboard_dashboard_id" FOREIGN KEY ("dashboard_id") REFERENCES "dashboard" ("id"));
CREATE TABLE IF NOT EXISTS "role" ("id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "type" TEXT NOT NULL, "org_id" TEXT NOT NULL, CONSTRAINT "pk_role" PRIMARY KEY ("id"), CONSTRAINT "fk_role_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "user_preference" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "value" TEXT NOT NULL, "user_id" TEXT NOT NULL, CONSTRAINT "pk_user_preference" PRIMARY KEY ("id"), CONSTRAINT "fk_user_preference_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id"));
CREATE TABLE IF NOT EXISTS "org_preference" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "value" TEXT NOT NULL, "org_id" TEXT NOT NULL, CONSTRAINT "pk_org_preference" PRIMARY KEY ("id"), CONSTRAINT "fk_org_preference_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "auth_domain" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "data" TEXT NOT NULL, "org_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_auth_domain" PRIMARY KEY ("id"), CONSTRAINT "fk_auth_domain_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "users" ("created_at" TIMESTAMP, "updated_at" TIMESTAMP, "id" TEXT NOT NULL, "display_name" TEXT NOT NULL, "email" TEXT NOT NULL, "org_id" TEXT NOT NULL, "is_root" BOOLEAN NOT NULL, "status" TEXT NOT NULL, CONSTRAINT "pk_users" PRIMARY KEY ("id"), CONSTRAINT "fk_users_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "planned_maintenance_rule" ("id" TEXT NOT NULL, "planned_maintenance_id" TEXT NOT NULL, "rule_id" TEXT NOT NULL, CONSTRAINT "pk_planned_maintenance_rule" PRIMARY KEY ("id"), CONSTRAINT "fk_planned_maintenance_rule_planned_maintenance_id" FOREIGN KEY ("planned_maintenance_id") REFERENCES "planned_maintenance" ("id"), CONSTRAINT "fk_planned_maintenance_rule_rule_id" FOREIGN KEY ("rule_id") REFERENCES "rule" ("id"));
CREATE TABLE IF NOT EXISTS "user_role" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "role_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_user_role" PRIMARY KEY ("id"), CONSTRAINT "fk_user_role_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id"), CONSTRAINT "fk_user_role_role_id" FOREIGN KEY ("role_id") REFERENCES "role" ("id"));
CREATE TABLE IF NOT EXISTS "service_account" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "org_id" TEXT NOT NULL, CONSTRAINT "pk_service_account" PRIMARY KEY ("id"), CONSTRAINT "fk_service_account_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "service_account_role" ("id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "service_account_id" TEXT NOT NULL, "role_id" TEXT NOT NULL, CONSTRAINT "pk_service_account_role" PRIMARY KEY ("id"), CONSTRAINT "fk_service_account_role_service_account_id" FOREIGN KEY ("service_account_id") REFERENCES "service_account" ("id"), CONSTRAINT "fk_service_account_role_role_id" FOREIGN KEY ("role_id") REFERENCES "role" ("id"));
CREATE TABLE IF NOT EXISTS "factor_api_key" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "key" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "expires_at" INTEGER NOT NULL, "last_observed_at" TIMESTAMP NOT NULL, "service_account_id" TEXT NOT NULL, CONSTRAINT "pk_factor_api_key" PRIMARY KEY ("id"), CONSTRAINT "fk_factor_api_key_service_account_id" FOREIGN KEY ("service_account_id") REFERENCES "service_account" ("id"));
CREATE TABLE IF NOT EXISTS "llm_pricing_rule" ("id" TEXT NOT NULL, "source_id" TEXT, "model" TEXT NOT NULL, "provider" TEXT NOT NULL, "model_pattern" TEXT NOT NULL, "unit" TEXT NOT NULL, "pricing" TEXT NOT NULL DEFAULT '{}', "is_override" BOOLEAN NOT NULL DEFAULT false, "synced_at" TIMESTAMP, "enabled" BOOLEAN NOT NULL DEFAULT true, "org_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "created_by" TEXT NOT NULL, "updated_by" TEXT NOT NULL, CONSTRAINT "pk_llm_pricing_rule" PRIMARY KEY ("id"), CONSTRAINT "fk_llm_pricing_rule_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "span_mapper_group" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "condition" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "org_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "created_by" TEXT NOT NULL, "updated_by" TEXT NOT NULL, CONSTRAINT "pk_span_mapper_group" PRIMARY KEY ("id"), CONSTRAINT "fk_span_mapper_group_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "span_mapper" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "field_context" TEXT NOT NULL, "config" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "group_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "created_by" TEXT NOT NULL, "updated_by" TEXT NOT NULL, CONSTRAINT "pk_span_mapper" PRIMARY KEY ("id"), CONSTRAINT "fk_span_mapper_group_id" FOREIGN KEY ("group_id") REFERENCES "span_mapper_group" ("id"));
CREATE TABLE IF NOT EXISTS "tag" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "org_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_tag" PRIMARY KEY ("id"), CONSTRAINT "fk_tag_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "tag_relation" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "resource_id" TEXT NOT NULL, "tag_id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_tag_relation" PRIMARY KEY ("id"), CONSTRAINT "fk_tag_relation_tag_id" FOREIGN KEY ("tag_id") REFERENCES "tag" ("id"));
CREATE TABLE IF NOT EXISTS "integration_dashboard" ("id" TEXT NOT NULL, "dashboard_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "slug" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_integration_dashboard" PRIMARY KEY ("id"), CONSTRAINT "fk_integration_dashboard_dashboard_id" FOREIGN KEY ("dashboard_id") REFERENCES "dashboard" ("id"));
CREATE TABLE IF NOT EXISTS "dashboard" ("id" TEXT NOT NULL, "created_at" TIMESTAMP, "updated_at" TIMESTAMP, "created_by" TEXT, "updated_by" TEXT, "data" TEXT NOT NULL, "locked" BOOLEAN NOT NULL DEFAULT false, "org_id" TEXT NOT NULL, "source" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "pk_dashboard" PRIMARY KEY ("id"), CONSTRAINT "fk_dashboard_org_id" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id"));
CREATE TABLE IF NOT EXISTS "changelog" ("store" TEXT NOT NULL, "object_type" TEXT NOT NULL, "object_id" TEXT NOT NULL, "relation" TEXT NOT NULL, "user_object_type" TEXT NOT NULL, "user_object_id" TEXT NOT NULL, "user_relation" TEXT NOT NULL, "condition_name" TEXT, "condition_context" BYTEA, "operation" INTEGER NOT NULL, "ulid" TEXT NOT NULL, "inserted_at" TIMESTAMP NOT NULL, CONSTRAINT "pk_changelog" PRIMARY KEY ("store", "ulid", "object_type"));
CREATE TABLE IF NOT EXISTS "cloud_integration_service" ("id" TEXT NOT NULL, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "type" TEXT NOT NULL, "config" TEXT, "cloud_integration_id" TEXT NOT NULL, CONSTRAINT "pk_cloud_integration_service" PRIMARY KEY ("id"), CONSTRAINT "fk_cloud_integration_service_cloud_integration_id" FOREIGN KEY ("cloud_integration_id") REFERENCES "cloud_integration" ("id"));
CREATE UNIQUE INDEX apdex_setting_unique_idx ON apdex_setting (service_name, org_id);
CREATE UNIQUE INDEX "idx_unique_name" ON "organizations" ("name");
CREATE UNIQUE INDEX "idx_unique_alias" ON "organizations" ("alias");
CREATE UNIQUE INDEX "idx_unique_key" ON "organizations" ("key");
CREATE UNIQUE INDEX "uq_factor_password_user_id" ON "factor_password" ("user_id");
CREATE UNIQUE INDEX "uq_reset_password_token_password_id" ON "reset_password_token" ("password_id");
CREATE UNIQUE INDEX "uq_reset_password_token_token" ON "reset_password_token" ("token");
CREATE UNIQUE INDEX "uq_auth_token_access_token" ON "auth_token" ("access_token");
CREATE UNIQUE INDEX "uq_auth_token_refresh_token" ON "auth_token" ("refresh_token");
CREATE UNIQUE INDEX "uq_tuple_ulid" ON "tuple" ("ulid");
CREATE UNIQUE INDEX "uq_public_dashboard_dashboard_id" ON "public_dashboard" ("dashboard_id");
CREATE UNIQUE INDEX "uq_role_name_org_id" ON "role" ("name", "org_id");
CREATE UNIQUE INDEX "uq_user_preference_name_user_id" ON "user_preference" ("name", "user_id");
CREATE UNIQUE INDEX "uq_org_preference_name_org_id" ON "org_preference" ("name", "org_id");
CREATE UNIQUE INDEX "uq_auth_domain_name_org_id" ON "auth_domain" ("name", "org_id");
CREATE UNIQUE INDEX "puq_cloud_integration_account_id_provider_org_id_67f5b2fc" ON "cloud_integration" ("account_id", "provider", "org_id") WHERE removed_at IS NULL;
CREATE UNIQUE INDEX "uq_user_role_user_id_role_id" ON "user_role" ("user_id", "role_id");
CREATE UNIQUE INDEX "puq_service_account_name_org_id_471d6134" ON "service_account" ("name", "org_id") WHERE status != 'deleted';
CREATE UNIQUE INDEX "puq_service_account_email_org_id_471d6134" ON "service_account" ("email", "org_id") WHERE status != 'deleted';
CREATE UNIQUE INDEX "uq_service_account_role_service_account_id_role_id" ON "service_account_role" ("service_account_id", "role_id");
CREATE UNIQUE INDEX "uq_factor_api_key_key" ON "factor_api_key" ("key");
CREATE UNIQUE INDEX "uq_factor_api_key_name_service_account_id" ON "factor_api_key" ("name", "service_account_id");
CREATE UNIQUE INDEX "puq_users_email_org_id_471d6134" ON "users" ("email", "org_id") WHERE status != 'deleted';
CREATE UNIQUE INDEX "puq_llm_pricing_rule_org_id_source_id_7a2889be" ON "llm_pricing_rule" ("org_id", "source_id") WHERE source_id IS NOT NULL;
CREATE UNIQUE INDEX "uq_span_mapper_group_org_id_name" ON "span_mapper_group" ("org_id", "name");
CREATE UNIQUE INDEX "uq_span_mapper_group_id_name" ON "span_mapper" ("group_id", "name");
CREATE UNIQUE INDEX "uq_tag_relation_kind_resource_id_tag_id" ON "tag_relation" ("kind", "resource_id", "tag_id");
CREATE UNIQUE INDEX "uq_integration_dashboard_dashboard_id" ON "integration_dashboard" ("dashboard_id");
CREATE UNIQUE INDEX "uq_cloud_integration_service_cloud_integration_id_type" ON "cloud_integration_service" ("cloud_integration_id", "type");
COMMIT;
